test('nonzero skipped is rejected',()=>errorCode(()=>parseTap(Buffer.from(tap(1,[['# skipped 0','# skipped 1']])),1),'TAP_COUNTS'));
test('nonzero todo is rejected',()=>errorCode(()=>parseTap(Buffer.from(tap(1,[['# todo 0','# todo 1']])),1),'TAP_COUNTS'));
