test('maintenance evidence requires the governed E-plus command in the current epoch',()=>withTemp(root=>{const left=path.join(root,'left'),right=path.join(root,'right');evidence(left,'replica-1');evidence(right,'replica-2');for(const item of [left,right]){fs.rmSync(path.join(item,'commands/e-plus-evaluator'),{recursive:true});remanifest(item);}assert.throws(()=>compareReplicaEvidence({leftRoot:left,rightRoot:right,leftDigest:digest,rightDigest:digest}),CIEvidenceError);}));
test('identical forged E-plus TAP fails against its envelope-bound count',()=>withTemp(root=>{const left=path.join(root,'left'),right=path.join(root,'right');evidence(left,'replica-1',E_PLUS_CONSTITUTIVE_CONTENT_PATHS);evidence(right,'replica-2',E_PLUS_CONSTITUTIVE_CONTENT_PATHS);const forged=Buffer.from(tap(23));mutateStream(left,'e-plus-evaluator','stdout',forged);mutateStream(right,'e-plus-evaluator','stdout',forged);assert.throws(()=>compareReplicaEvidence({leftRoot:left,rightRoot:right,leftDigest:digest,rightDigest:digest}),CIEvidenceError);}));
test('workflow declares regular-file guards, controller trigger paths and stateful bindings in every replica',()=>{const workflow=fs.readFileSync(new URL('../../../.github/workflows/gate-2-evidence.yml',import.meta.url),'utf8');assert.equal(workflow.match(/for governed_path in/g)?.length,3);assert.equal(workflow.match(/test -f "\$governed_path"/g)?.length,3);assert.equal(workflow.match(/test ! -L "\$governed_path"/g)?.length,3);for(const governedPath of [...CI_MAINTENANCE_PATHS,...GATE_2_CONTROLLER_CONTENT_PATHS,'tools/core-conformance/lib/stateful-validator.mjs','tools/core-conformance/test/stateful-history-reference.test.mjs'])assert.ok(workflow.includes(governedPath));assert.equal(workflow.match(/--expected-stateful-module-sha /g)?.length,2);assert.equal(workflow.match(/--expected-stateful-test-sha /g)?.length,2);});
test('identical raw-summary forgeries fail for both governed epochs',()=>withTemp(root=>{for(const[paths,label]of [[CI_MAINTENANCE_PATHS,'current'],[BOUNDED_CONSTITUTIVE_CONTENT_PATHS,'prospective']]){const left=path.join(root,`${label}-left`),right=path.join(root,`${label}-right`);evidence(left,'replica-1',paths);evidence(right,'replica-2',paths);const forged=Buffer.from(JSON.stringify({classification:'STATEFUL_HISTORY_REFERENCE_FOUNDATION',scenario_count:1,scenario_runs_passed:1,stateful_complete_requirements:1,stateful_projection_requirements:7,technical_verdict:'NOT_EVALUATED',conformance_claimed:false,results:[{scenario_id:'forged'}]})+'\n');mutateStream(left,'check-stateful','stdout',forged);mutateStream(right,'check-stateful','stdout',forged);errorCode(()=>compareReplicaEvidence({leftRoot:left,rightRoot:right,leftDigest:digest,rightDigest:digest}),'RAW_SUMMARY_BINDING');}}));
test('comparison document rejects V1, unknown, duplicate, missing and forged nested bindings',()=>withTemp(root=>{const left=path.join(root,'left'),right=path.join(root,'right');evidence(left,'replica-1');evidence(right,'replica-2');const value=compareReplicaEvidence({leftRoot:left,rightRoot:right,leftDigest:digest,rightDigest:digest});assert.equal(validateComparisonDocument(value),value);const duplicate={...envelope(),changed_path_count:2,changed_paths:[CI_MAINTENANCE_PATHS[0],CI_MAINTENANCE_PATHS[0]]};for(const mutation of [{schema_version:'janus-ci-gate2-comparison-v1'},{unknown:true},{run_id:'0'},{commit:'c'.repeat(40)},{normalized_results:{forged:true}},{change_envelope:duplicate}])assert.throws(()=>validateComparisonDocument({...value,...mutation}),CIEvidenceError);const missing=structuredClone(value);delete missing.normalized_results.run.technical_verdict;assert.throws(()=>validateComparisonDocument(missing),CIEvidenceError);}));
test('Git object IDs require lowercase repository SHA-1 hex width',()=>{assert.equal(validateGitObjectId('b'.repeat(40)),'b'.repeat(40));for(const value of ['b'.repeat(39),'b'.repeat(64),'g'.repeat(40),'B'.repeat(40)])errorCode(()=>validateGitObjectId(value),'GIT_OID_INVALID');});
test('timeout records signal and leaves a valid partial manifest',async()=>withTempAsync(async root=>{writePartialManifest(root,'INITIAL');await rejectCode(()=>runRecordedCommand({id:'timeout',args:[process.execPath,'-e','setTimeout(()=>{},10000)'],cwd:root,evidenceDir:root,expectedExit:0,timeoutMs:25}),'COMMAND_TIMEOUT');const metadata=JSON.parse(fs.readFileSync(path.join(root,'commands/timeout/result.json'),'utf8'));assert.equal(metadata.timeout,true);const partial=JSON.parse(fs.readFileSync(path.join(root,'manifest.partial.json'),'utf8'));assert.equal(partial.status,'PARTIAL');assert.ok(partial.entries.length>0);}));
test('spawn error still records raw streams, result and partial manifest',async()=>withTempAsync(async root=>{writePartialManifest(root,'INITIAL');await rejectCode(()=>runRecordedCommand({id:'spawn-error',args:[path.join(root,'does-not-exist')],cwd:root,evidenceDir:root,expectedExit:0,timeoutMs:1000}),'COMMAND_SPAWN');for(const file of ['stdout.raw','stderr.raw','result.json'])assert.equal(fs.existsSync(path.join(root,'commands/spawn-error',file)),true);const metadata=JSON.parse(fs.readFileSync(path.join(root,'commands/spawn-error/result.json')));assert.equal(typeof metadata.spawn_error,'string');assert.equal(fs.existsSync(path.join(root,'manifest.partial.json')),true);}));
test('npm ci accepts silent and ignore-scripts exactly once and rejects substitutions or duplicates',()=>{const args=['npm','ci','--ignore-scripts','--no-audit','--no-fund','--update-notifier=false','--engine-strict','--loglevel=silent','--cache','c','--userconfig','u','--globalconfig','g'];assert.equal(validateNpmCiArgs(args),true);assert.equal(args.filter(value=>value==='--loglevel=silent').length,1);assert.equal(args.filter(value=>value==='--ignore-scripts').length,1);const error=[...args];error[7]='--loglevel=error';errorCode(()=>validateNpmCiArgs(error),'NPM_CI_FLAGS');const substitution=[...args];substitution[2]='--foreground-scripts';errorCode(()=>validateNpmCiArgs(substitution),'NPM_CI_FLAGS');errorCode(()=>validateNpmCiArgs(args.filter(value=>value!=='--ignore-scripts')),'NPM_CI_FLAGS');errorCode(()=>validateNpmCiArgs([...args,'--ignore-scripts']),'NPM_CI_FLAGS');errorCode(()=>validateNpmCiArgs([...args,'--loglevel=silent']),'NPM_CI_FLAGS');errorCode(()=>validateNpmCiArgs([...args,'--no-audit']),'NPM_CI_FLAGS');for(const command of ['run','start','test','exec']){const disallowed=[...args];disallowed[1]=command;errorCode(()=>validateNpmCiArgs(disallowed),'NPM_CI_FLAGS');}const same=[...args];same[13]='u';errorCode(()=>validateNpmCiArgs(same),'NPM_CI_CONFIG');});
test('npm ci accepts only a silent valid outcome',()=>{const valid={exit:0,expected_exit:0,signal:null,timeout:false,output_limit:false,spawn_error:null,stdout:Buffer.alloc(0),stderr:Buffer.alloc(0)};assert.equal(validateNpmCiResult(valid),true);errorCode(()=>validateNpmCiResult({...valid,stdout:Buffer.from('x')}),'NPM_CI_STDOUT_NONEMPTY');errorCode(()=>validateNpmCiResult({...valid,stderr:Buffer.from('x')}),'NPM_CI_STDERR_NONEMPTY');errorCode(()=>validateNpmCiResult({...valid,exit:1}),'NPM_CI_OUTCOME_INVALID');});
