test('nonzero silent npm failure records raw streams, result and partial manifest fail-closed',async()=>withTempAsync(async root=>{writePartialManifest(root,'INITIAL');const args=[process.execPath,'-e','process.stdout.write("out");process.stderr.write("err");process.exit(7)','--','--loglevel=silent'];await rejectCode(()=>runRecordedCommand({id:'npm-ci-silent-failure',args,cwd:root,evidenceDir:root,expectedExit:0,timeoutMs:1000,outcomeErrorCode:'NPM_CI_OUTCOME_INVALID'}),'NPM_CI_OUTCOME_INVALID');const dir=path.join(root,'commands/npm-ci-silent-failure');assert.equal(fs.readFileSync(path.join(dir,'stdout.raw'),'utf8'),'out');assert.equal(fs.readFileSync(path.join(dir,'stderr.raw'),'utf8'),'err');const result=JSON.parse(fs.readFileSync(path.join(dir,'result.json')));assert.equal(result.exit,7);assert.equal(result.expected_exit,0);assert.equal(result.signal,null);assert.equal(result.timeout,false);assert.equal(result.output_limit,false);assert.equal(result.spawn_error,null);const partial=JSON.parse(fs.readFileSync(path.join(root,'manifest.partial.json')));assert.equal(partial.status,'PARTIAL');assert.ok(partial.entries.some(entry=>entry.relative_path==='commands/npm-ci-silent-failure/stdout.raw'));}));
